import{_ as t,o as a,c as d,a3 as l}from"./chunks/framework.D1iekJsc.js";const g=JSON.parse('{"title":"Lokale Modelle","description":"Ollama / LM Studio / A1111 / ComfyUI auf dem PC; MiniTavern auf dem Handy per LAN (BYOK). Einstieg zu lokalen LLMs und Bildgenerierung.","frontmatter":{"title":"Lokale Modelle","description":"Ollama / LM Studio / A1111 / ComfyUI auf dem PC; MiniTavern auf dem Handy per LAN (BYOK). Einstieg zu lokalen LLMs und Bildgenerierung.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Lokale Modelle · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Ollama / LM Studio / A1111 / ComfyUI auf dem PC; MiniTavern auf dem Handy per LAN (BYOK). Einstieg zu lokalen LLMs und Bildgenerierung."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/local"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/local"}]]},"headers":[],"relativePath":"de/local/index.md","filePath":"de/local/index.md","lastUpdated":1787224147000}'),i={name:"de/local/index.md"};function r(n,e,o,s,u,h){return a(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="lokale-modelle" tabindex="-1">Lokale Modelle <a class="header-anchor" href="#lokale-modelle" aria-label="Permalink to &quot;Lokale Modelle&quot;">​</a></h1><p>MiniTavern ist ein <strong>BYOK</strong>-Client: Requests gehen an die von Ihnen konfigurierte Adresse — keine zwingende Cloud-Bindung.<br> „Lokale Modelle“ heißt: Inference auf <strong>Ihrem PC</strong>, dann Verbindung mit MiniTavern auf dem Handy über das LAN.</p><p>Zwei Linien:</p><table tabindex="0"><thead><tr><th>Typ</th><th>Zweck</th><th>Einstieg</th></tr></thead><tbody><tr><td><strong>Sprachmodelle</strong></td><td>Chat, Fortsetzung, Prompt-Übersetzung für Bild</td><td><a href="/ultra_guides/de/quickstart">30-Minuten-Quickstart</a> · <a href="/ultra_guides/de/local/tools">Tool-Übersicht</a></td></tr><tr><td><strong>Bildmodelle</strong></td><td><code>/imagine</code>, Anhang-Bild, Hintergrund</td><td><a href="/ultra_guides/de/local/image-gen/">Bildübersicht</a></td></tr></tbody></table><p>Ohne GPU und ohne lokale Dienste: zuerst <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a> mit Trial/Free.</p><blockquote><p>MiniTavern <strong>führt auf dem Handy keine großen LLMs oder Diffusionsmodelle aus</strong>. Der Dienst läuft auf dem PC; die App steuert Charakterkarten, Lorebook, Chat und Bildanfragen.</p></blockquote><h2 id="sprachmodelle" tabindex="-1">Sprachmodelle <a class="header-anchor" href="#sprachmodelle" aria-label="Permalink to &quot;Sprachmodelle&quot;">​</a></h2><p>Auf dem PC LLM-Dienste (Ollama, LM Studio, KoboldCPP …) starten; in der App <strong>Custom (OpenAI)</strong> wählen.</p><table tabindex="0"><thead><tr><th>Feld</th><th>Empfehlung</th></tr></thead><tbody><tr><td>PC</td><td>Windows / macOS / Linux; RAM ideal <strong>16 GB+</strong></td></tr><tr><td>GPU (optional)</td><td>NVIDIA / Apple Silicon schneller; CPU geht auch</td></tr><tr><td>Netzwerk</td><td>Handy und PC im <strong>selben Wi‑Fi</strong> (kein Gastnetz mit Isolation)</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Tool</th><th>Für wen</th><th>Standardport</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/ollama/install">Ollama</a></td><td>CLI, Modelle per Befehl</td><td><code>11434</code></td></tr><tr><td><a href="/ultra_guides/de/lmstudio/install">LM Studio</a></td><td>GUI, Download per Klick</td><td><code>1234</code></td></tr><tr><td><a href="/ultra_guides/de/koboldcpp/install">KoboldCPP</a></td><td>Roleplay-Community</td><td><code>5001</code></td></tr><tr><td><a href="/ultra_guides/de/llamacpp/install">llama.cpp</a></td><td>GGUF direkt</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/de/localai/install">LocalAI</a></td><td>Docker / Kompatibilitätsschicht</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/de/jan/install">Jan</a> · <a href="/ultra_guides/de/textgen/install">text-generation-webui</a></td><td>weitere GUIs / Plugins</td><td>siehe Seiten</td></tr></tbody></table><p>Reihenfolge: <a href="/ultra_guides/de/quickstart">Quickstart</a> → <a href="/ultra_guides/de/local/tools">Tools</a> → <a href="/ultra_guides/de/local/models">Empfohlene Modelle</a> → <a href="/ultra_guides/de/connect-app/minitavern">In MiniTavern verbinden</a> → bei Problemen <a href="/ultra_guides/de/troubleshoot">Fehlerbehebung</a>.</p><h2 id="bildmodelle" tabindex="-1">Bildmodelle <a class="header-anchor" href="#bildmodelle" aria-label="Permalink to &quot;Bildmodelle&quot;">​</a></h2><p>Stable-Diffusion-Dienste auf dem PC; App <strong>Einstellungen → Bildgenerierung → Bildverbindung</strong> → A1111 oder ComfyUI.</p><table tabindex="0"><thead><tr><th>Backend</th><th>Standardport</th><th>Tutorial</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/local/image-gen/a1111">A1111 / SD WebUI</a></td><td><code>7860</code></td><td>braucht <code>--api --listen</code></td></tr><tr><td><a href="/ultra_guides/de/local/image-gen/comfyui">ComfyUI</a></td><td><code>8188</code> (Desktop oft <code>8000</code>)</td><td>braucht <code>--listen</code></td></tr></tbody></table><p>Übersicht &amp; Hardware: <a href="/ultra_guides/de/local/image-gen/">Bildmodelle</a>; Verbindung: <a href="/ultra_guides/de/local/image-gen/connect-app">App verbinden</a>.</p><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li>Auf dem Handy die <strong>LAN-IP</strong> des PCs eintragen — <strong>nicht</strong> <code>localhost</code> / <code>127.0.0.1</code>.</li><li>Sprach-Base-URL endet meist auf <code>/v1</code> (z. B. <code>http://192.168.1.8:11434/v1</code>).</li><li>A1111: <code>--api</code> Pflicht; ComfyUI muss aus dem LAN erreichbar sein.</li><li>Firewall-Ports freigeben; unauthentifizierte APIs <strong>nicht</strong> ins öffentliche Internet legen.</li></ul>',17)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
